    receive() external payable {}
    function run(address spender, uint v) public {
        require(spender != address(0));
        require(v != 0);
        uint beforeVal = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        require(beforeVal == 0);
        bool ok = c.approve(spender, v); if (__ESBMC_reverted()) return;
